/**
 * Returns the standard copyright string used in our games.
 *
 * @param {string} gameName - The game's friendly name
 * @param {number} releaseYear - The year it was first released
 *
 * * @example
 * getCopyrightString('Nevada', 2021);
 */
export function getCopyrightString(gameName: string, releaseYear: number): string {
    const currentYear = new Date().getFullYear();
    return `${gameName} © tombola Ltd. ${currentYear > releaseYear ? `${releaseYear} - ${currentYear}` : releaseYear}`;
}
